package dev.byteplus.render;

import dev.byteplus.util.Theme;

public final class MenuBackground {
   private static final FullscreenPass PASS = new FullscreenPass("Menu background", FRAG());
   private static double time;
   private static long last = System.nanoTime();

   private MenuBackground() {
   }

   public static boolean draw(float intro, float warp, float mx, float my, float holeX, float holeY, float holeSize) {
      long now = System.nanoTime();
      time = time + Math.min(0.1, (now - last) / 1.0E9);
      last = now;
      return PASS.draw(p -> {
         p.set1("uTime", (float)time);
         p.set1("uIntro", intro);
         p.set1("uWarp", warp);
         p.set2("uMouse", mx, my);
         p.set2("uHole", holeX, 1.0F - holeY);
         p.set1("uHoleSize", holeSize);
         p.setRgb("uAccent", Theme.ACCENT);
         p.setRgb("uAccent2", Theme.HUD_ACCENT_2);
      });
   }

   private static String FRAG() {
      return "#version 330 core\nin vec2 vNdc;\nout vec4 fragColor;\nuniform vec2 uRes;\nuniform float uTime, uIntro, uWarp, uHoleSize;\nuniform vec2 uMouse, uHole;\nuniform vec3 uAccent, uAccent2;\n\nfloat hash12(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }\nvec2 hash22(vec2 p) { vec3 q = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); q += dot(q, q.yzx + 33.33); return fract((q.xx + q.yz) * q.zy); }\nfloat noise2(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    f = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash12(i), hash12(i + vec2(1, 0)), f.x), mix(hash12(i + vec2(0, 1)), hash12(i + vec2(1, 1)), f.x), f.y);\n}\nfloat fbm(vec2 p) {\n    float a = 0.5, s = 0.0;\n    mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n    for (int i = 0; i < 5; i++) { s += a * noise2(p); p = m * p + vec2(3.1, 7.4); a *= 0.5; }\n    return s;\n}\nmat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }\n\n// domain-warped nebula, tinted toward the theme colours\nvec3 nebula(vec2 p, float t) {\n    vec2 q = vec2(fbm(p * 1.1 + vec2(0.0, t * 0.012)), fbm(p * 1.1 + vec2(5.2, 1.3) - t * 0.01));\n    vec2 r = vec2(fbm(p * 1.5 + 3.2 * q + vec2(1.7, 9.2) + t * 0.018), fbm(p * 1.5 + 3.2 * q + vec2(8.3, 2.8)));\n    float f = fbm(p * 1.3 + 2.6 * r);\n    vec3 deep = vec3(0.010, 0.007, 0.024);\n    vec3 purple = mix(vec3(0.26, 0.07, 0.48), uAccent2 * 0.5, 0.25);\n    vec3 blue = mix(vec3(0.05, 0.16, 0.48), uAccent * 0.45, 0.2);\n    vec3 col = deep;\n    col = mix(col, purple, clamp(f * f * 2.0, 0.0, 1.0));\n    col = mix(col, blue, clamp(dot(q, q) * 0.45 * r.y, 0.0, 1.0) * 0.55);\n    col += uAccent * pow(clamp(f - 0.5, 0.0, 1.0), 2.0) * 1.3;\n    return col * (0.45 + 0.55 * f);\n}\n\n// one layer of stars; 'streak' stretches them radially (hyperspace)\nvec3 starLayer(vec2 p, float scale, float thresh, float t, vec2 dir, float streak) {\n    vec2 g = p * scale;\n    vec2 id = floor(g), f = fract(g) - 0.5;\n    float h = hash12(id);\n    if (h < thresh) return vec3(0.0);\n    vec2 o = hash22(id) - 0.5;\n    vec2 d = f - o * 0.7;\n    vec2 perp = vec2(-dir.y, dir.x);\n    float dl = abs(dot(d, dir)) / (1.0 + streak * 6.0);\n    float dp = abs(dot(d, perp));\n    float dist = length(vec2(dl, dp));\n    float tw = 0.6 + 0.4 * sin(t * (1.0 + h * 5.0) + h * 40.0);\n    float b = (0.012 / (dist * dist + 0.0016)) * 0.0025 * tw;\n    b += smoothstep(0.08, 0.0, dist) * 0.6 * tw;\n    vec3 tint = mix(vec3(0.7, 0.8, 1.0), vec3(1.0, 0.85, 0.65), hash12(id + 7.0));\n    return tint * b * (1.0 + streak * 2.0);\n}\n\nvoid main() {\n    float t = uTime;\n    float aspect = uRes.x / uRes.y;\n    vec2 p = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    vec2 hc = (uHole - 0.5) * vec2(aspect, 1.0) - uMouse * 0.02;\n\n    // warp transition: everything rushes toward the hole\n    float w = uWarp * uWarp;\n    p = hc + (p - hc) * (1.0 - 0.8 * w);\n\n    float intro = smoothstep(0.0, 1.0, uIntro);\n    float rs = uHoleSize * (0.15 + 0.85 * smoothstep(0.15, 0.9, uIntro));\n    vec2 r = p - hc;\n    float d = length(r);\n    vec2 rn = r / max(d, 1e-4);\n\n    // gravitational lensing: the background around the hole is pushed outward (Einstein ring)\n    float bend = rs * rs * 1.7 / max(d, rs * 0.6);\n    vec2 lp = p + rn * bend;\n\n    // background: nebula + three star layers with parallax\n    vec2 drift = vec2(t * 0.004, t * 0.0015);\n    vec3 col = nebula(lp * 1.15 - uMouse * 0.05 + drift, t);\n    float streak = pow(1.0 - intro, 2.0) * 3.0 + w * 4.0;\n    vec2 sdir = normalize(lp - hc + 1e-4);\n    col += starLayer(lp - uMouse * 0.010 + drift * 0.5, 34.0, 0.80, t, sdir, streak);\n    col += starLayer(lp - uMouse * 0.022 + drift * 0.8, 58.0, 0.86, t, sdir, streak) * 0.8;\n    col += starLayer(lp - uMouse * 0.040 + drift * 1.3, 110.0, 0.90, t, sdir, streak) * 0.6;\n\n    // shadow\n    float shadow = smoothstep(rs * 1.02, rs * 0.95, d);\n\n    // accretion disk, tilted so we see it nearly edge-on\n    vec2 q = rot(-0.22) * r;\n    float tilt = 0.24;\n    vec2 e = vec2(q.x, q.y / tilt);\n    float er = length(e);\n    float ang = atan(e.y, e.x);\n    float inner = rs * 1.5, outer = rs * 4.6;\n    float band = smoothstep(inner, inner * 1.18, er) * (1.0 - smoothstep(outer * 0.62, outer, er));\n    float spin = t * 1.6 * pow(rs / max(er, rs), 1.5);\n    float swirl = fbm(vec2(ang * 2.5 + spin * 3.0, log(max(er, 1e-4)) * 7.0 - t * 0.2));\n    float streaks = 0.55 + 0.45 * sin(ang * 14.0 + spin * 8.0 + swirl * 6.0);\n    float heat = smoothstep(outer * 0.7, inner, er);\n    vec3 hot = mix(mix(uAccent2 * 0.9, uAccent, heat), vec3(1.0, 0.97, 0.9), pow(heat, 2.5));\n    float beam = 0.55 + 0.75 * (0.5 + 0.5 * cos(ang + 0.4));      // approaching side brighter\n    vec3 disk = hot * band * (0.35 + 0.9 * swirl) * streaks * beam * 2.2;\n    // the far half of the disk passes behind the shadow\n    if (q.y > 0.0) disk *= (1.0 - shadow);\n\n    // the far side of the disk, lensed up and over the shadow (the \"halo\")\n    float ringR = rs * 1.28, ringW = rs * 0.34;\n    float halo = exp(-pow((d - ringR) / ringW, 2.0));\n    float hang = atan(rn.y, rn.x);\n    float hswirl = fbm(vec2(hang * 3.0 - t * 0.9, d * 9.0 / rs));\n    float upper = smoothstep(-0.35, 0.6, rn.y);\n    vec3 haloCol = mix(uAccent, vec3(1.0, 0.95, 0.85), 0.35) * halo * (0.35 + 0.8 * hswirl) * (0.35 + 0.9 * upper) * 1.4;\n\n    // photon ring + glow\n    float photon = exp(-pow((d - rs * 1.04) / (rs * 0.035), 2.0));\n    vec3 glow = uAccent * exp(-max(d - rs, 0.0) / (rs * 1.8)) * 0.32;\n\n    col *= (1.0 - shadow);\n    col += disk + haloCol * (1.0 - shadow) + vec3(1.0, 0.93, 0.8) * photon * 1.1 + glow * (1.0 - shadow * 0.7);\n\n    // arrival flash, warp fade\n    col += vec3(1.0, 0.95, 0.85) * (1.0 - smoothstep(0.0, 0.22, uIntro)) * 1.2;\n    col *= smoothstep(0.0, 0.12, uIntro + 0.05);\n    col = mix(col, vec3(0.0), smoothstep(0.55, 1.0, uWarp));\n\n    // vignette, filmic curve, grain\n    float v = length(vNdc * vec2(0.85, 1.0));\n    col *= 1.0 - 0.5 * pow(v * 0.72, 2.4);\n    col = 1.0 - exp(-col * 1.25);\n    col += (hash12(gl_FragCoord.xy + fract(t) * 91.7) - 0.5) / 96.0;\n    fragColor = vec4(max(col, 0.0), 1.0);\n}\n";
   }
}
